def is_sorted(lst):
    if len(lst) <= 1:
        return True

    seen = {}
    for i in range(len(lst)):
        if lst[i] in seen:
            seen[lst[i]] += 1
            if seen[lst[i]] > 2:
                return False
        else:
            seen[lst[i]] = 1

        if i > 0 and lst[i] < lst[i - 1]:
            return False

    return True

